package com.adib.maintenance;
import android.app.*;import android.view.*;import android.widget.*;import android.content.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.shadows.ShadowAlertDialog;import java.lang.reflect.*;import java.time.Duration;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={24,28,35}) public class EquipmentViewsTest {
 JSONObject previous;boolean required;MainActivity a;
 @Before public void before()throws Exception{previous=AccountSession.user;required=AccountSession.required;AccountSession.user=new JSONObject().put("id","equipment-test").put("role","admin");AccountSession.required=true;a=Robolectric.buildActivity(MainActivity.class).get();prefs(a).prefs.edit().clear().commit();a.getPreferences(0).edit().clear().commit();seed(a);}
 @After public void after(){prefs(a).prefs.edit().clear().commit();AccountSession.user=previous;AccountSession.required=required;System.setProperty("adib.testing","true");}
 void set(Object a,String n,Object v)throws Exception{Field f=a.getClass().getDeclaredField(n);f.setAccessible(true);f.set(a,v);}Object get(Object a,String n)throws Exception{Field f=a.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(a);}
 Object call(Object a,String n,Class<?>[] types,Object... args)throws Exception{Method m=a.getClass().getDeclaredMethod(n,types);m.setAccessible(true);return m.invoke(a,args);}Object call(String n)throws Exception{return call(a,n,new Class<?>[]{});}
 EquipmentViewPreferences prefs(MainActivity a){try{return (EquipmentViewPreferences)call(a,"equipmentViews",new Class<?>[]{});}catch(Exception e){throw new RuntimeException(e);}}
 JSONObject task(String id)throws Exception{return new JSONObject().put("id",id).put("title",id).put("sourceKey","todo").put("process","Not started").put("completed",false);}
 void seed(MainActivity a)throws Exception{set(a,"mode","equipment");set(a,"screen","canvas");set(a,"plans",new JSONArray().put(new JSONObject().put("id","root").put("name","ADIB").put("tasks",new JSONArray().put(task("root-task")))).put(new JSONObject().put("id","child").put("parentId","root").put("name","Child")).put(new JSONObject().put("id","other").put("name","Other")));set(a,"equipment",new JSONArray().put(new JSONObject().put("id","machine").put("name","Machine").put("planId","child").put("tasks",new JSONArray().put(task("machine-task")))).put(new JSONObject().put("id","foreign").put("name","Foreign").put("planId","other").put("tasks",new JSONArray().put(task("foreign-task")))));set(a,"currentPlanId","root");set(a,"currentMachineId","");}
 void view(String name)throws Exception{call(a,"setEquipmentView",new Class<?>[]{String.class},name);Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();}
 AlertDialog latest(){Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();return ShadowAlertDialog.getLatestAlertDialog();}
 void clickRow(AlertDialog d,String label){ListView l=d.getListView();for(int i=0;i<l.getAdapter().getCount();i++)if(label.equals(l.getAdapter().getItem(i).toString())){l.performItemClick(l.getChildAt(i),i,l.getAdapter().getItemId(i));return;}fail("Missing menu row: "+label);}
 @Test public void boardMenuHasListAndDefaultChoice()throws Exception{call(a,"showCanvasContextMenu",new Class<?>[]{JSONObject.class},(JSONObject)null);AlertDialog d=latest();clickRow(d,"Siyahı rejimi");assertEquals("list",get(a,"screen"));assertNotNull(((View)get(a,"root")).findViewWithTag("work-list-task:machine-task"));assertNull(((View)get(a,"root")).findViewWithTag("work-list-task:foreign-task"));call(a,"showCanvasContextMenu",new Class<?>[]{JSONObject.class},(JSONObject)null);clickRow(latest(),"Defolt görünüş");assertEquals(4,latest().getListView().getAdapter().getCount());}
 @Test public void pickerHasAllThreeModesAndScopeStaysUnchanged()throws Exception{call("showEquipmentViewPicker");AlertDialog d=latest();assertEquals(3,d.getListView().getAdapter().getCount());clickRow(d,"Siyahı");assertEquals("root",get(a,"currentPlanId"));view("kanban");JSONArray ts=(JSONArray)call("tasksForBoard");assertEquals(2,ts.length());view("canvas");assertEquals("root",get(a,"currentPlanId"));assertEquals("canvas",get(a,"screen"));}
 @Test public void fixedDefaultPersistsAcrossActivityAndDoesNotBecomeLast()throws Exception{prefs(a).setDefault("list");view("kanban");assertEquals("list",prefs(a).resolveDefault());MainActivity next=Robolectric.buildActivity(MainActivity.class).get();seed(next);call(next,"openEquipment",new Class<?>[]{});assertEquals("list",get(next,"screen"));assertEquals("list",prefs(next).chosenDefault());}
 @Test public void rememberLastOnlyWhenChosen()throws Exception{prefs(a).setDefault("last");view("kanban");MainActivity next=Robolectric.buildActivity(MainActivity.class).get();seed(next);call(next,"openEquipment",new Class<?>[]{});assertEquals("kanban",get(next,"screen"));view("list");assertEquals("list",prefs(a).resolveDefault());}
 @Test public void defaultDialogCancelDoesNotSaveOrSwitch()throws Exception{call("showEquipmentDefaultView");AlertDialog d=latest();clickRow(d,"Siyahı");d.getButton(-2).performClick();assertEquals("canvas",prefs(a).chosenDefault());assertEquals("canvas",get(a,"screen"));}
 @Test public void defaultDialogSaveDoesNotReplaceCurrentView()throws Exception{view("kanban");call("showEquipmentDefaultView");AlertDialog d=latest();clickRow(d,"Siyahı");d.getButton(-1).performClick();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertEquals("list",prefs(a).chosenDefault());assertEquals("kanban",get(a,"screen"));call("openEquipment");assertEquals("list",get(a,"screen"));}
 @Test public void machineScopeDoesNotExpandOnViewSwitch()throws Exception{set(a,"currentMachineId","machine");view("list");assertNotNull(((View)get(a,"root")).findViewWithTag("work-list-task:machine-task"));assertNull(((View)get(a,"root")).findViewWithTag("work-list-task:root-task"));view("kanban");assertEquals(1,((JSONArray)call("tasksForBoard")).length());assertEquals("machine",get(a,"currentMachineId"));}
 @Test public void deferredSnapshotKeepsChosenViewAndLoadsTasks()throws Exception{set(a,"plans",new JSONArray());set(a,"equipment",new JSONArray());prefs(a).setDefault("kanban");call("openEquipment");assertEquals("kanban",get(a,"screen"));JSONObject data=new JSONObject().put("plans",new JSONArray().put(new JSONObject().put("id","root").put("name","ADIB"))).put("equipment",new JSONArray().put(new JSONObject().put("id","machine").put("name","Machine").put("planId","root").put("tasks",new JSONArray().put(task("loaded")))));call(a,"applyPlanSnapshot",new Class<?>[]{JSONObject.class},data);call("render");assertEquals("kanban",get(a,"screen"));assertEquals(1,((JSONArray)call("tasksForBoard")).length());}
 @Test public void preferencesAreProfileScopedAndCorruptValuesFallBack()throws Exception{System.setProperty("adib.testing","false");prefs(a).prefs.edit().clear().commit();prefs(a).setDefault("list");AccountSession.user=new JSONObject().put("id","another-user").put("role","admin");assertEquals("canvas",prefs(a).resolveDefault());prefs(a).prefs.edit().putString("default","invalid").putString("last","invalid").commit();assertEquals("canvas",prefs(a).resolveDefault());prefs(a).prefs.edit().clear().commit();AccountSession.user=new JSONObject().put("id","equipment-test").put("role","admin");assertEquals("list",prefs(a).resolveDefault());}
}
